30	    29	/**
31	    30	 * This abstract class implements some common functionalities of the
32	    31	 * the generic mapper, reducer and combiner classes of Aggregate.
33	    32	 */
34	    33	@InterfaceAudience.Public
35	    34	@InterfaceStability.Stable
36	    35	public class ValueAggregatorJobBase<K1 extends WritableComparable<?>,
37	    36	                                             V1 extends Writable>
38	    37	{
39	    38	  public static final String DESCRIPTOR = "mapreduce.aggregate.descriptor";
40	    39	  public static final String DESCRIPTOR_NUM = 
41	    40	    "mapreduce.aggregate.descriptor.num";
42	    41	  public static final String USER_JAR = "mapreduce.aggregate.user.jar.file";
43	    42	  
44	    43	  protected static ArrayList<ValueAggregatorDescriptor> aggregatorDescriptorList = null;
45	    44	
46	    45	  public static void setup(Configuration job) {
47	    46	    initializeMySpec(job);
48	    47	    logSpec();
49	    48	  }
50	    49	
51	    50	  protected static ValueAggregatorDescriptor getValueAggregatorDescriptor(
52	    51	      String spec, Configuration conf) {
53	    52	    if (spec == null)
54	    53	      return null;
55	    54	    String[] segments = spec.split(",", -1);
56	    55	    String type = segments[0];
57	    56	    if (type.compareToIgnoreCase("UserDefined") == 0) {
58	    57	      String className = segments[1];
59	    58	      return new UserDefinedValueAggregatorDescriptor(className, conf);
60	    59	    }
61	    60	    return null;
62	    61	  }
63	    62	
64	    63	  protected static ArrayList<ValueAggregatorDescriptor> getAggregatorDescriptors(
65	    64	      Configuration conf) {
66	    65	    int num = conf.getInt(DESCRIPTOR_NUM, 0);
67	    66	    ArrayList<ValueAggregatorDescriptor> retv = 
68	    67	      new ArrayList<ValueAggregatorDescriptor>(num);
69	    68	    for (int i = 0; i < num; i++) {
70	    69	      String spec = conf.get(DESCRIPTOR + "." + i);
71	    70	      ValueAggregatorDescriptor ad = getValueAggregatorDescriptor(spec, conf);
72	    71	      if (ad != null) {
73	    72	        retv.add(ad);
74	    73	      }
75	    74	    }
76	    75	    return retv;
77	    76	  }
78	    77	
79	    78	  private static void initializeMySpec(Configuration conf) {
80	    79	    aggregatorDescriptorList = getAggregatorDescriptors(conf);
81	    80	    if (aggregatorDescriptorList.size() == 0) {
82	    81	      aggregatorDescriptorList
83	    82	          .add(new UserDefinedValueAggregatorDescriptor(
84	    83	              ValueAggregatorBaseDescriptor.class.getCanonicalName(), conf));
85	    84	    }
86	    85	  }
87	    86	
88	    87	  protected static void logSpec() {
89	    88	  }
90	    89	}
