137	    46	  /**
138	    47	   *  the map function. It iterates through the value aggregator descriptor 
139	    48	   *  list to generate aggregation id/value pairs and emit them.
140	    49	   */
141	    50	  public void map(K1 key, V1 value,
142	    51	      Context context) throws IOException, InterruptedException  {
143	    52	
144	    53	    Iterator<?> iter = 
145	    54	      ValueAggregatorJobBase.aggregatorDescriptorList.iterator();
146	    55	    while (iter.hasNext()) {
147	    56	      ValueAggregatorDescriptor ad = (ValueAggregatorDescriptor) iter.next();
148	    57	      Iterator<Entry<Text, Text>> ens =
149	    58	        ad.generateKeyValPairs(key, value).iterator();
150	    59	      while (ens.hasNext()) {
151	    60	        Entry<Text, Text> en = ens.next();
152	    61	        context.write(en.getKey(), en.getValue());
153	    62	      }
154	    63	    }
155	    64	  }
