201	    44	  /**
202	    45	   * @param key
203	    46	   *        the key is expected to be a Text object, whose prefix indicates
204	    47	   *        the type of aggregation to aggregate the values. In effect, data
205	    48	   *        driven computing is achieved. It is assumed that each aggregator's
206	    49	   *        getReport method emits appropriate output for the aggregator. This
207	    50	   *        may be further customized.
208	    51	   * @param values the values to be aggregated
209	    52	   * @param context 
210	    53	   */
211	    54	  public void reduce(Text key, Iterable<Text> values,
212	    55	      Context context) throws IOException, InterruptedException {
213	    56	    String keyStr = key.toString();
214	    57	    int pos = keyStr.indexOf(ValueAggregatorDescriptor.TYPE_SEPARATOR);
215	    58	    String type = keyStr.substring(0, pos);
216	    59	    keyStr = keyStr.substring(pos + 
217	    60	               ValueAggregatorDescriptor.TYPE_SEPARATOR.length());
218	    61	    long uniqCount = context.getConfiguration().
219	    62	      getLong(UniqValueCount.MAX_NUM_UNIQUE_VALUES, Long.MAX_VALUE);
220	    63	    ValueAggregator aggregator = ValueAggregatorBaseDescriptor
221	    64	      .generateValueAggregator(type, uniqCount);
222	    65	    for (Text value : values) {
223	    66	      aggregator.addNextValue(value);
224	    67	    }
225	    68	
226	    69	    String val = aggregator.getReport();
227	    70	    key = new Text(keyStr);
228	    71	    context.write(key, new Text(val));
229	    72	  }
230	    73	}
