package org.apache.hadoop.examples;

import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;
import org.apache.hadoop.mapreduce.Job;
import org.apache.hadoop.mapreduce.MapReduceTestUtil;
import org.apache.hadoop.mapreduce.lib.aggregate.ValueAggregatorJob;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Tests the {@link AggregateWordCount} example. The user supplied
 * aggregator descriptor has to be picked up by the Aggregate framework,
 * otherwise the job silently falls back to the default descriptor and
 * reports record counts instead of word counts.
 */
public class TestAggregateWordCount {

  private final Configuration conf = new Configuration();

  private final Path rootDir = new Path(
      System.getProperty("test.build.data", "target/test-dir"),
      "TestAggregateWordCount");

  private final Path inputDir = new Path(rootDir, "input");

  private final Path outputDir = new Path(rootDir, "output");

  @Before
  public void setUp() throws Exception {
    FileSystem fs = FileSystem.getLocal(conf);
    fs.delete(rootDir, true);
    fs.mkdirs(inputDir);
    try (OutputStream out = fs.create(new Path(inputDir, "words.txt"))) {
      out.write("Hello World\nHello Hadoop\n".getBytes(StandardCharsets.UTF_8));
    }
  }

  @After
  public void tearDown() throws Exception {
    FileSystem.getLocal(conf).delete(rootDir, true);
  }

  @SuppressWarnings("unchecked")
  @Test
  public void testAggregateWordCount() throws Exception {
    Job job = ValueAggregatorJob.createValueAggregatorJob(
        new String[] {inputDir.toString(), outputDir.toString(), "1",
            "textinputformat"},
        new Class[] {AggregateWordCount.WordCountPlugInClass.class});
    job.setJarByClass(AggregateWordCount.class);

    assertTrue("The aggregate word count job failed.",
        job.waitForCompletion(true));
    assertEquals("Hadoop\t1\nHello\t2\nWorld\t1\n",
        MapReduceTestUtil.readOutput(outputDir, job.getConfiguration()));
  }
}

